// Where the visitor is, roughly, from their browser's time zone alone: no permission prompt, and nothing is sent
// anywhere. The zone is looked up in assets/js/tz-places.js (each zone's reference city, generated by
// scripts/timezones.py), so a Seattle visitor, in America/Los_Angeles, gets Los Angeles: close enough for the sky.
import { ZONES, ALIASES } from './tz-places.js';

/** { zone, lat, lon } in degrees, north and east positive. lat is null when the zone isn't a place (UTC, Etc/GMT+5). */
export function visitorPlace(date = new Date()) {
  let zone = '';
  try { zone = Intl.DateTimeFormat().resolvedOptions().timeZone || ''; } catch { /* no Intl time zones: use the offset */ }
  const hit = ZONES[zone] || ZONES[ALIASES[zone]];
  if (hit) return { zone, lat: hit[0], lon: hit[1] };
  // not a place, but the clock's offset from UTC still gives a longitude: 15 degrees an hour
  return { zone, lat: null, lon: -date.getTimezoneOffset() / 4 };
}
